package main
import("os";"strings";"testing")
func TestOneClickCheckIsNativeProductSnapshot(t *testing.T){html,err:=os.ReadFile("web/index.html");if err!=nil{t.Fatal(err)};js:=requireProductScript(t,"web/app/lenses/orient-investigate.js");all:=string(html)+"\n"+js;for _,want:=range []string{"Sentinel 2.4","missionRibbon","evidenceStage","renderSnapshot","Run Snapshot","/api/quick-check","/api/review-queue","Attention index","Evidence boundary"}{if !strings.Contains(all,want){t.Fatalf("snapshot missing %q",want)}};for _,bad:=range []string{"/api/actions/execute","/api/changes/start","/api/trust/capture","sudo ","rm -"}{if strings.Contains(js,bad){t.Fatalf("snapshot/investigation module contains mutation %q",bad)}}}
func TestMainRegistersVaultIsolationReadEndpoint(t *testing.T){mainFile,err:=os.ReadFile("main.go");if err!=nil{t.Fatal(err)};text:=string(mainFile);if !strings.Contains(text,"mux.HandleFunc(\"/api/actions/vault/isolation\""){t.Fatal("Vault isolation route missing")};if !strings.Contains(text,"a.handleVaultIsolation"){t.Fatal("Vault isolation handler missing")}}
